import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:horizon_launcher/core/theme/horizon_motion.dart';
import 'package:horizon_launcher/core/theme/horizon_theme.dart';
import 'package:horizon_launcher/core/widgets/horizon_widgets.dart';

/// Pixel golden GENERATION. Run in CI with:
///   flutter test --dart-define=GENERATE_GOLDENS=true --update-goldens \
///     test/golden_generation_test.dart
/// and publish `test/goldens/*.png` as artifacts.
///
/// HONEST LIMITATION: a committed baseline PNG generated by the same Flutter
/// engine version is required for a real *comparison* pass. Until that baseline
/// is checked in, this generates baselines only; it does NOT claim a comparison
/// test passed. `flutter test` normally skips it (no false green).
const bool kGenerateGoldens = bool.fromEnvironment('GENERATE_GOLDENS');

void main() {
  testWidgets('premium card golden baseline', (WidgetTester tester) async {
    if (!kGenerateGoldens) {
      return; // explicitly not a comparison test yet
    }
    await tester.pumpWidget(MaterialApp(
      home: Scaffold(
        backgroundColor: HorizonPalette.background,
        body: Center(
          child: SizedBox(
            width: 320,
            height: 120,
            child: StaggeredEntrance(
              child: HorizonCard(
                glow: true,
                child: const Center(child: Text('HORIZON')),
              ),
            ),
          ),
        ),
      ),
    ));
    await tester.pumpAndSettle();
    await expectLater(
      find.byType(HorizonCard),
      matchesGoldenFile('goldens/premium_card.png'),
    );
  }, skip: !kGenerateGoldens);
}
